B.aa7=s(["\u098f\u0996\u09a8 \u09aa\u09cd\u09b0\u09a4\u09bf \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09c7 \u09e9\u09e6 \u09b8\u09c7\u0995\u09c7\u09a8\u09cd\u09a1, \u0986\u0997\u09c7 \u099b\u09bf\u09b2 \u09e7\u09eb \u2014 \u09a1\u09c7\u0987\u09b2\u09bf \u0995\u09c1\u0987\u099c, \u099a\u09cd\u09af\u09be\u09aa\u09cd\u099f\u09be\u09b0 \u09b8\u09c7\u099f \u0993 \u09ac\u09cd\u09af\u09be\u099f\u09b2 \u09b8\u09ac\u0996\u09be\u09a8\u09c7\u0964","\u09aa\u09cd\u09b0\u09b6\u09cd\u09a8 \u0986\u09b0 \u099a\u09be\u09b0\u099f\u09be \u0985\u09aa\u09b6\u09a8 \u098f\u0996\u09a8 \u098f\u0995 \u09b8\u09cd\u0995\u09cd\u09b0\u09bf\u09a8\u09c7\u0987 \u09a0\u09bf\u0995 \u09b9\u09af\u09bc, \u09b8\u09cd\u0995\u09cd\u09b0\u09b2 \u0995\u09b0\u09a4\u09c7 \u09b9\u09af\u09bc \u09a8\u09be\u0964","\u09a1\u09c7\u0987\u09b2\u09bf \u0995\u09c1\u0987\u099c\u09c7\u09b0 \u09ac\u09cd\u09af\u09be\u09a8\u09be\u09b0 \u09aa\u09cd\u09b0\u09a5\u09ae \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8\u09c7 \u09a6\u09c7\u0996\u09be\u09af\u09bc, \u09a4\u09be\u09b0\u09aa\u09b0 \u0986\u09b0 \u09a6\u09c7\u0996\u09be\u09af\u09bc \u09a8\u09be\u0964","\u09aa\u09cd\u09b0\u09cb\u09ab\u09be\u0987\u09b2 \u0985\u09cd\u09af\u09be\u09ad\u09be\u099f\u09be\u09b0\u09c7 \u0986\u09b0 \u09ae\u09be\u09a5\u09be\u09b0 \u0989\u09aa\u09b0\u09c7\u09b0 \u0985\u0982\u09b6 \u0995\u09be\u099f\u09be \u09af\u09be\u09af\u09bc \u09a8\u09be\u0964",u.f],t.s)
B.ac9=s(["\u0905\u092c \u0939\u0930 \u0938\u0935\u093e\u0932 \u092e\u0947\u0902 30 \u0938\u0947\u0915\u0902\u0921, \u092a\u0939\u0932\u0947 \u0925\u0947 15 \u2014 \u0921\u0947\u0932\u0940 \u0915\u094d\u0935\u093f\u091c\u093c, \u091a\u0948\u092a\u094d\u091f\u0930 \u0938\u0947\u091f \u0914\u0930 \u092c\u0948\u091f\u0932, \u0924\u0940\u0928\u094b\u0902 \u092e\u0947\u0902\u0964","\u0938\u0935\u093e\u0932 \u0914\u0930 \u091a\u093e\u0930\u094b\u0902 \u0935\u093f\u0915\u0932\u094d\u092a \u0905\u092c \u090f\u0915 \u0939\u0940 \u0938\u094d\u0915\u094d\u0930\u0940\u0928 \u092e\u0947\u0902 \u0906 \u091c\u093e\u0924\u0947 \u0939\u0948\u0902, \u0938\u094d\u0915\u094d\u0930\u0949\u0932 \u0928\u0939\u0940\u0902 \u0915\u0930\u0928\u093e \u092a\u0921\u093c\u0924\u093e\u0964","\u0921\u0947\u0932\u0940 \u0915\u094d\u0935\u093f\u091c\u093c \u0915\u093e \u092c\u0948\u0928\u0930 \u092a\u0939\u0932\u0947 \u0938\u0935\u093e\u0932 \u092a\u0930 \u0926\u093f\u0916\u0924\u093e \u0939\u0948, \u0909\u0938\u0915\u0947 \u092c\u093e\u0926 \u0928\u0939\u0940\u0902\u0964","\u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932 \u0905\u0935\u0924\u093e\u0930 \u092e\u0947\u0902 \u0938\u093f\u0930 \u0915\u093e \u090a\u092a\u0930\u0940 \u0939\u093f\u0938\u094d\u0938\u093e \u0905\u092c \u0915\u091f\u0924\u093e \u0928\u0939\u0940\u0902\u0964","\u092c\u0902\u0917\u093e\u0932\u0940 \u0914\u0930 \u0939\u093f\u0928\u094d\u0926\u0940 \u092e\u0947\u0902 \u0938\u0935\u093e\u0932 \u0915\u0947 \u0928\u0940\u091a\u0947 \u0905\u092c \u0905\u0932\u0917 \u0938\u0947 \u0905\u0902\u0917\u094d\u0930\u0947\u091c\u093c\u0940 \u0932\u093e\u0907\u0928 \u0928\u0939\u0940\u0902 \u0926\u093f\u0916\u0924\u0940\u0964"],t.s)
